"use client"

import { useState, useEffect } from "react"
import axios from "axios"
import Sidebar from "../Sidebar" // Ajustez le chemin si nécessaire
import Header from "../../Function/Header" // Ajustez le chemin si nécessaire
import { Trash2, Edit2, Plus, AlertCircle, Loader2 } from "lucide-react"

export default function Zones() {
  const [isCollapsed, setIsCollapsed] = useState(false)
  const [zones, setZones] = useState([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [editZone, setEditZone] = useState(null)
  const [formData, setFormData] = useState({ zoneName: "" })
  const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false)
  const [zoneToDelete, setZoneToDelete] = useState(null)

  // Récupérer le rôle depuis localStorage
  const userRole = localStorage.getItem("role") || "Inconnu"

  useEffect(() => {
    fetchZones()
  }, [])

  const fetchZones = async () => {
    const token = localStorage.getItem("token")
    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.")
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/zones`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      setZones(response.data || [])
    } catch (error) {
      setError(error.response?.data?.message || "Échec de la récupération des zones.")
      console.error("Erreur lors de la récupération des zones :", error.response?.data || error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleCreateOrUpdate = async (e) => {
    e.preventDefault()
    const token = localStorage.getItem("token")
    if (!token || userRole !== "Deputydirector") return

    try {
      if (editZone) {
        const response = await axios.put(
          `${process.env.REACT_APP_API_URL}/api/zones/${editZone._id}`,
          { zoneName: formData.zoneName },
          { headers: { Authorization: `Bearer ${token}` } },
        )
        setZones(zones.map((zone) => (zone._id === editZone._id ? response.data : zone)))
      } else {
        const response = await axios.post(
          `${process.env.REACT_APP_API_URL}/api/zones`,
          { zoneName: formData.zoneName },
          { headers: { Authorization: `Bearer ${token}` } },
        )
        setZones([...zones, response.data])
      }
      setModalOpen(false)
      setEditZone(null)
      setFormData({ zoneName: "" })
    } catch (error) {
      setError(error.response?.data?.message || "Échec de l'enregistrement de la zone.")
      console.error("Erreur lors de l'enregistrement de la zone :", error.response?.data || error)
    }
  }

  const handleDelete = async () => {
    const token = localStorage.getItem("token")
    if (!token || userRole !== "Deputydirector" || !zoneToDelete) return

    try {
      await axios.delete(`${process.env.REACT_APP_API_URL}/api/zones/${zoneToDelete}`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      setZones(zones.filter((zone) => zone._id !== zoneToDelete))
      setConfirmDeleteOpen(false)
      setZoneToDelete(null)
    } catch (error) {
      setError(error.response?.data?.message || "Échec de la suppression de la zone.")
      console.error("Erreur lors de la suppression de la zone :", error.response?.data || error)
    }
  }

  const openModal = (zone = null) => {
    if (userRole !== "Deputydirector") return
    setEditZone(zone)
    setFormData({ zoneName: zone ? zone.zoneName : "" })
    setModalOpen(true)
  }

  const openConfirmDelete = (zoneId) => {
    if (userRole !== "Deputydirector") return
    setZoneToDelete(zoneId)
    setConfirmDeleteOpen(true)
  }

  const sidebarItems = [
    { title: "Tableau de bord", icon: "Home", href: "/dashboard" },
    { title: "Zones", icon: "Map", href: "/zones" },
    { title: "Livraisons", icon: "Truck", href: "/deliveries" },
  ]

  return (
    <>
      <div>
        <Header toggleMenu={() => setIsCollapsed(!isCollapsed)} />
      </div>
      <div className="min-h-screen flex">
        <Sidebar isCollapsed={isCollapsed} closeMenu={setIsCollapsed} items={sidebarItems} />
        <div
          className={`flex-1 flex flex-col transition-all duration-300 ${
            isCollapsed ? "ml-[80px]" : "ml-[250px]"
          }`}
        >
          <main className="flex-1 overflow-y-auto p-4 sm:p-6 mt-20">
            <div className="max-w-5xl mx-auto">
              <div className="bg-white rounded-xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50 mb-6">
                <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 sm:p-6">
                  <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                    <div>
                      <h1 className="text-xl sm:text-2xl font-bold tracking-tight">Gestion des Zones</h1>
                      <p className="text-white/80 mt-1 text-xs sm:text-sm">
                        Gérer les zones de stockage et d'emplacement
                      </p>
                    </div>
                    {userRole === "Deputydirector" && (
                      <button
                        onClick={() => openModal()}
                        className="px-3 py-1.5 sm:px-4 sm:py-2 bg-[#00717F] hover:bg-[#00717F/10] rounded-md text-white text-sm sm:text-base font-medium flex items-center gap-2 transition-colors w-full sm:w-auto justify-center sm:justify-start"
                      >
                        <Plus className="h-4 w-4 sm:h-5 sm:w-5" />
                        Ajouter une zone
                      </button>
                    )}
                  </div>
                </div>

                <div className="p-4 sm:p-6">
                  {error && (
                    <div className="p-3 sm:p-4 mb-4 sm:mb-6 rounded-r-md bg-red-50 border-l-4 border-red-500 flex items-center gap-3">
                      <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-red-500 flex-shrink-0" />
                      <p className="text-xs sm:text-sm text-red-700">{error}</p>
                    </div>
                  )}

                  {isLoading ? (
                    <div className="flex justify-center items-center h-48 sm:h-64">
                      <div className="flex flex-col items-center gap-2">
                        <Loader2 className="h-8 w-8 sm:h-10 sm:w-10 text-[#00717F] animate-spin" />
                        <p className="text-[#00717F] text-xs sm:text-sm font-medium">Chargement des zones...</p>
                      </div>
                    </div>
                  ) : zones.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-48 sm:h-64 text-gray-500">
                      <svg className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" />
                      </svg>
                      <p className="text-center text-sm sm:text-base">Aucune zone trouvée.</p>
                    </div>
                  ) : (
                    <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                        <thead className="bg-[#F5F6FA]">
                          <tr>
                            <th className="px-4 sm:px-6 py-3 text-left text-xs sm:text-sm font-medium text-[#00717F] uppercase tracking-wider">
                              Nom de la zone
                            </th>
                            {userRole === "Deputydirector" && (
                              <th className="px-4 sm:px-6 py-3 text-left text-xs sm:text-sm font-medium text-[#00717F] uppercase tracking-wider">
                                Actions
                              </th>
                            )}
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                          {zones.map((zone) => (
                            <tr key={zone._id} className="hover:bg-[#F5F6FA]/50 transition-colors">
                              <td className="px-4 sm:px-6 py-3 sm:py-4 whitespace-nowrap text-xs sm:text-sm text-gray-900">
                                {zone.zoneName}
                              </td>
                              {userRole === "Deputydirector" && (
                                <td className="px-4 sm:px-6 py-3 sm:py-4 whitespace-nowrap text-xs sm:text-sm text-gray-500">
                                  <div className="flex items-center gap-2">
                                    <button
                                      onClick={() => openModal(zone)}
                                      className="p-1.5 sm:p-2 text-[#00717F] hover:bg-[#00717F]/10 rounded-full transition-colors"
                                      aria-label="Edit"
                                    >
                                      <Edit2 className="h-3 w-3 sm:h-4 sm:w-4" />
                                    </button>
                                    <button
                                      onClick={() => openConfirmDelete(zone._id)}
                                      className="p-1.5 sm:p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors"
                                      aria-label="Delete"
                                    >
                                      <Trash2 className="h-3 w-3 sm:h-4 sm:w-4" />
                                    </button>
                                  </div>
                                </td>
                              )}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </main>
        </div>
      </div>

      {/* Add/Edit Zone Modal */}
      {modalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-xl p-0 w-full max-w-md overflow-hidden animate-fadeIn">
            <div className="bg-[#00717F] text-white p-3 sm:p-4 flex justify-between items-center">
              <h3 className="text-lg sm:text-xl font-semibold">
                {editZone ? "Modifier la zone" : "Ajouter une zone"}
              </h3>
              <button
                onClick={() => setModalOpen(false)}
                className="rounded-full p-1 hover:bg-white/20 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleCreateOrUpdate} className="p-4 sm:p-6 space-y-4 sm:space-y-5">
              <div>
                <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Nom de la zone</label>
                <input
                  type="text"
                  value={formData.zoneName}
                  onChange={(e) => setFormData({ ...formData, zoneName: e.target.value })}
                  className="w-full px-3 py-2 border border-[#C8A45D/30] rounded-md focus:ring-2 focus:ring-[#00717F] focus:border-transparent text-xs sm:text-sm"
                  required
                />
              </div>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setModalOpen(false)}
                  className="px-3 py-1.5 sm:px-4 sm:py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 text-xs sm:text-sm"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  className="px-3 py-1.5 sm:px-4 sm:py-2 bg-[#00717F] text-white rounded-md hover:bg-[#C8A45D] transition-colors text-xs sm:text-sm"
                >
                  {editZone ? "Mettre à jour" : "Créer"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
      {/* Confirm Delete Modal */}
      {confirmDeleteOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-xl p-0 w-full max-w-md overflow-hidden animate-fadeIn">
            <div className="bg-[#00717F] text-white p-3 sm:p-4 flex justify-between items-center">
              <h3 className="text-lg sm:text-xl font-semibold">Confirmer la suppression</h3>
              <button
                onClick={() => setConfirmDeleteOpen(false)}
                className="rounded-full p-1 hover:bg-white/20 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="p-4 sm:p-6 space-y-4">
              <p className="text-xs sm:text-sm text-gray-700">
                Êtes-vous sûr de vouloir supprimer cette zone ? Cette action est irréversible.
              </p>
              <div className="flex justify-end gap-2">
                <button
                  onClick={() => setConfirmDeleteOpen(false)}
                  className="px-3 py-1.5 sm:px-4 sm:py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 text-xs sm:text-sm"
                >
                  Annuler
                </button>
                <button
                  onClick={handleDelete}
                  className="px-3 py-1.5 sm:px-4 sm:py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors text-xs sm:text-sm"
                >
                  Supprimer
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style jsx global>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.2s ease-out forwards;
        }
      `}</style>
    </>
  )
}
